def test_parse_natural_roundtable_query():
    question, personas, inferred = _parse_natural_roundtable_query(
        [
            "Brandon,",
            "Margaret,",
            "and",
            "Jennifer",
            "to",
            "debate",
            "the",
            "relevance",
            "of",
            "Formal",
            "Methods",
            "in",
            "large",
            "scale",
            "aerospace",
            "projects",
            "in",
            "2026",
        ]
    )

    assert inferred is True
    assert personas == "Brandon,Margaret,Jennifer"
    assert question == "the relevance of Formal Methods in large scale aerospace projects in 2026"


def test_parse_participant_specs_separates_persona_from_protocol_role():
    participants = parse_participant_specs(
        "Brandon:failure_mode,Margaret:evidence_auditor,Jennifer:complexity_minimizer"
    )

    assert [p["persona"] for p in participants] == ["Brandon", "Margaret", "Jennifer"]
    assert [p["protocol_role"] for p in participants] == [
        "failure_mode",
        "evidence_auditor",
        "complexity_minimizer",
    ]
    assert participants[0]["role_label"] == "Failure Mode Analyst"


def test_default_parallel_participants_uses_focus_labels():
    participants = default_parallel_participants(3, focus="correctness,tests,maintainability")

    assert [p["persona"] for p in participants] == ["correctness", "tests", "maintainability"]
    assert participants[0]["protocol_role"] == "failure_mode"


def test_parse_protocol_turn_keeps_raw_when_invalid_json():
    parsed = parse_protocol_turn("not json")

    assert parsed["parse_ok"] is False
    assert parsed["raw_content"] == "not json"
    assert parsed["critiques"][0]["issue_type"] == "format"


def test_date_sensitive_question_detection():
    assert is_date_sensitive_question("formal methods in aerospace projects in 2026")
    assert is_date_sensitive_question("latest aerospace certification guidance")
    assert not is_date_sensitive_question("formal methods in aerospace")
